{
  "name": "@joe-broadhead/opencode-mem",
  "version": "0.9.14",
  "type": "module",
  "description": "Durable private and shared-space memory for OpenCode agents",
  "license": "MIT",
  "main": "./index.js",
  "exports": {
    ".": "./index.js"
  },
  "engines": {
    "node": ">=22.13"
  },
  "jelly": {
    "title": "Memory",
    "summary": "Your decisions, preferences and notes, across conversations and agents.",
    "icon": "assets/icon.svg",
    "instructions": "docs/agent-instructions.md",
    "tools": [
      {
        "name": "mem.recall",
        "permission": "mem_recall",
        "effect": "allow",
        "readOnly": true
      },
      {
        "name": "mem.remember",
        "permission": "mem_remember",
        "effect": "allow",
        "readOnly": false
      },
      {
        "name": "mem.revise",
        "permission": "mem_revise",
        "effect": "allow",
        "readOnly": false
      },
      {
        "name": "mem.page",
        "permission": "mem_page",
        "effect": "allow",
        "readOnly": false
      },
      {
        "name": "mem.commitments",
        "permission": "mem_commitments",
        "effect": "allow",
        "readOnly": false
      },
      {
        "name": "mem.share",
        "permission": "mem_share",
        "effect": "allow",
        "readOnly": false
      },
      {
        "name": "mem.spaces",
        "permission": "mem_spaces",
        "effect": "allow",
        "readOnly": false
      },
      {
        "name": "mem.wiki",
        "permission": "mem_wiki",
        "effect": "allow",
        "readOnly": false
      },
      {
        "name": "mem.ingest",
        "permission": "mem_ingest",
        "effect": "allow",
        "readOnly": false
      },
      {
        "name": "mem.cursor",
        "permission": "mem_cursor",
        "effect": "allow",
        "readOnly": true
      },
      {
        "name": "mem.collect",
        "permission": "mem_collect",
        "effect": "allow",
        "readOnly": false
      },
      {
        "name": "mem.forget",
        "permission": "mem_forget",
        "effect": "allow",
        "readOnly": true
      },
      {
        "name": "mem.promote",
        "permission": "mem_promote",
        "effect": "allow",
        "readOnly": true
      },
      {
        "name": "mem.status",
        "permission": "mem_status",
        "effect": "allow",
        "readOnly": true
      },
      {
        "name": "mem.grants",
        "permission": "mem_grants",
        "effect": "allow",
        "readOnly": true
      },
      {
        "name": "mem.members",
        "permission": "mem_members",
        "effect": "allow",
        "readOnly": true
      }
    ],
    "skills": [
      "mem.usage",
      "mem.pages",
      "mem.sharing",
      "mem.sources"
    ],
    "rpc": [
      {
        "name": "memory.overview",
        "label": "say whether memory is connected and how much it holds",
        "permission": "mem_status",
        "readOnly": true,
        "input": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "jellySpeaker": {
              "type": "string"
            }
          }
        },
        "output": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "connected",
            "credential",
            "capture",
            "health"
          ],
          "properties": {
            "connected": {
              "type": "boolean"
            },
            "reason": {
              "type": "string",
              "maxLength": 400
            },
            "state": {
              "type": "string",
              "enum": [
                "unconfigured",
                "refused",
                "unreachable"
              ]
            },
            "credential": {
              "type": "string",
              "enum": [
                "jelly",
                "key",
                "option",
                "opencode",
                "none"
              ]
            },
            "refused": {
              "type": "string",
              "maxLength": 40
            },
            "address": {
              "type": "string",
              "maxLength": 300
            },
            "capture": {
              "type": "boolean"
            },
            "health": {
              "type": "string",
              "enum": [
                "ok",
                "unreachable",
                "unknown"
              ]
            },
            "extraction": {
              "type": "string",
              "enum": [
                "healthy",
                "failing",
                "unknown"
              ]
            },
            "failing_since": {
              "type": "string",
              "maxLength": 40
            },
            "records": {
              "type": "string",
              "enum": [
                "ok",
                "unavailable"
              ]
            },
            "spool": {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "depth"
              ],
              "properties": {
                "depth": {
                  "type": "integer",
                  "minimum": 0
                },
                "oldest": {
                  "type": "string",
                  "maxLength": 40
                }
              }
            },
            "space": {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "id",
                "name",
                "kind"
              ],
              "properties": {
                "id": {
                  "type": "string",
                  "maxLength": 200
                },
                "name": {
                  "type": "string",
                  "maxLength": 200
                },
                "kind": {
                  "type": "string",
                  "enum": [
                    "personal",
                    "shared",
                    "unknown"
                  ]
                }
              }
            },
            "counts": {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "memories",
                "conversations",
                "summaries",
                "profile"
              ],
              "properties": {
                "memories": {
                  "type": "integer",
                  "minimum": 0
                },
                "conversations": {
                  "type": "integer",
                  "minimum": 0
                },
                "summaries": {
                  "type": "integer",
                  "minimum": 0
                },
                "profile": {
                  "type": "boolean"
                }
              }
            }
          }
        }
      },
      {
        "name": "spaces.list",
        "label": "list your memory spaces",
        "permission": "mem_spaces",
        "readOnly": true,
        "input": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "jellySpeaker": {
              "type": "string"
            }
          }
        },
        "output": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "spaces"
          ],
          "properties": {
            "spaces": {
              "type": "array",
              "maxItems": 100,
              "items": {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "id",
                  "name",
                  "kind",
                  "role"
                ],
                "properties": {
                  "id": {
                    "type": "string",
                    "maxLength": 200
                  },
                  "name": {
                    "type": "string",
                    "maxLength": 200
                  },
                  "kind": {
                    "type": "string",
                    "enum": [
                      "personal",
                      "shared",
                      "unknown"
                    ]
                  },
                  "role": {
                    "type": "string",
                    "maxLength": 40
                  }
                }
              }
            }
          }
        }
      },
      {
        "name": "memories.recent",
        "label": "list your newest memories",
        "permission": "mem_recall",
        "readOnly": true,
        "input": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "offset": {
              "type": "integer",
              "minimum": 0,
              "maximum": 50,
              "multipleOf": 50
            },
            "space": {
              "type": "string",
              "maxLength": 200
            },
            "agent": {
              "type": "string",
              "maxLength": 200
            },
            "task": {
              "type": "string",
              "maxLength": 200
            },
            "jellySpeaker": {
              "type": "string"
            }
          }
        },
        "output": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "space",
            "spaces",
            "incomplete",
            "items",
            "more"
          ],
          "properties": {
            "space": {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "id",
                "name",
                "kind"
              ],
              "properties": {
                "id": {
                  "type": "string",
                  "maxLength": 200
                },
                "name": {
                  "type": "string",
                  "maxLength": 200
                },
                "kind": {
                  "type": "string",
                  "enum": [
                    "personal",
                    "shared",
                    "unknown"
                  ]
                }
              }
            },
            "spaces": {
              "type": "array",
              "maxItems": 100,
              "items": {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "id",
                  "name",
                  "kind"
                ],
                "properties": {
                  "id": {
                    "type": "string",
                    "maxLength": 200
                  },
                  "name": {
                    "type": "string",
                    "maxLength": 200
                  },
                  "kind": {
                    "type": "string",
                    "enum": [
                      "personal",
                      "shared",
                      "unknown"
                    ]
                  }
                }
              }
            },
            "incomplete": {
              "type": "array",
              "maxItems": 100,
              "items": {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "id",
                  "name",
                  "reason"
                ],
                "properties": {
                  "id": {
                    "type": "string",
                    "maxLength": 200
                  },
                  "name": {
                    "type": "string",
                    "maxLength": 200
                  },
                  "reason": {
                    "type": "string",
                    "maxLength": 200
                  }
                }
              }
            },
            "items": {
              "type": "array",
              "maxItems": 50,
              "items": {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "id",
                  "text",
                  "type",
                  "at",
                  "space",
                  "status",
                  "version",
                  "copies"
                ],
                "properties": {
                  "id": {
                    "type": "string",
                    "maxLength": 200
                  },
                  "text": {
                    "type": "string",
                    "maxLength": 600
                  },
                  "type": {
                    "type": "string",
                    "maxLength": 40
                  },
                  "at": {
                    "type": "string",
                    "maxLength": 40
                  },
                  "space": {
                    "type": "object",
                    "additionalProperties": false,
                    "required": [
                      "id",
                      "name"
                    ],
                    "properties": {
                      "id": {
                        "type": "string",
                        "maxLength": 200
                      },
                      "name": {
                        "type": "string",
                        "maxLength": 200
                      }
                    }
                  },
                  "status": {
                    "type": "string",
                    "maxLength": 20
                  },
                  "stated_by": {
                    "type": "string",
                    "enum": [
                      "person",
                      "agent",
                      "inferred",
                      "external"
                    ]
                  },
                  "source": {
                    "type": "string",
                    "maxLength": 200
                  },
                  "agent": {
                    "type": "string",
                    "maxLength": 80
                  },
                  "task": {
                    "type": "string",
                    "maxLength": 200
                  },
                  "version": {
                    "type": "integer",
                    "minimum": 0
                  },
                  "copies": {
                    "type": "object",
                    "additionalProperties": false,
                    "properties": {
                      "supersedes": {
                        "type": "array",
                        "maxItems": 20,
                        "items": {
                          "type": "string",
                          "maxLength": 200
                        }
                      },
                      "supersededBy": {
                        "type": "string",
                        "maxLength": 200
                      }
                    }
                  }
                }
              }
            },
            "more": {
              "type": "boolean"
            }
          }
        }
      },
      {
        "name": "wiki.list",
        "label": "list your wikis",
        "permission": "mem_wiki",
        "readOnly": true,
        "input": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "jellySpeaker": {
              "type": "string"
            }
          }
        },
        "output": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "wikis"
          ],
          "properties": {
            "wikis": {
              "type": "array",
              "maxItems": 100,
              "items": {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "id",
                  "name",
                  "pages"
                ],
                "properties": {
                  "id": {
                    "type": "string",
                    "maxLength": 200
                  },
                  "name": {
                    "type": "string",
                    "maxLength": 200
                  },
…[文件过长——仅保留首 16KB 与末 8KB]…
pc": []
      },
      {
        "v": 1,
        "id": "remembered",
        "place": "tool-result",
        "title": "Saved to memory",
        "tools": [
          "mem.remember",
          "mem.revise",
          "mem.commitments"
        ],
        "page": "views/remembered.html",
        "grants": [
          "data"
        ],
        "rpc": []
      }
    ],
    "signIns": [],
    "contributes": {
      "homeFeeds": [],
      "homeWidgets": [],
      "workKinds": [
        {
          "id": "recall",
          "label": "Searching memory",
          "icon": "file-text",
          "tools": [
            "mem.recall",
            "mem.status",
            "mem.cursor",
            "mem.wiki",
            "mem.members",
            "mem.grants"
          ]
        },
        {
          "id": "remember",
          "label": "Saving to memory",
          "icon": "work",
          "tools": [
            "mem.remember",
            "mem.commitments",
            "mem.revise",
            "mem.page"
          ]
        },
        {
          "id": "organise",
          "label": "Organising memory",
          "icon": "wrench",
          "tools": [
            "mem.spaces",
            "mem.share",
            "mem.promote",
            "mem.forget",
            "mem.collect",
            "mem.ingest"
          ]
        }
      ],
      "settings": [
        {
          "key": "controlURL",
          "label": "Memory address",
          "type": "string",
          "description": "The Memory server to use, such as https://mem.example.com. Leave it empty to use the one your Jelly account offers."
        },
        {
          "key": "capture",
          "label": "Remember conversations",
          "type": "boolean",
          "default": true,
          "description": "On by default: finished turns are saved to your private memory. Off: the memory tools still work, and nothing is saved unless the agent is asked to remember it."
        },
        {
          "key": "skipAsks",
          "label": "Run without asking",
          "type": "string",
          "description": "Empty by default. Memory's asks to turn off, separated by commas, such as memory.forget, page.delete; a deny still stands. The full list is in Memory's docs/permissions.md. A team write held in your Inbox still waits there."
        },
        {
          "key": "token",
          "label": "Memory key",
          "type": "secret",
          "description": "Only needed when your Jelly account does not sign you in to Memory: paste the key from Memory's /account page."
        }
      ]
    },
    "resources": [
      "memory"
    ],
    "asks": [
      "memory.forget",
      "memory.promote",
      "wiki.write",
      "wiki.delete",
      "memory.revise",
      "page.write",
      "page.delete",
      "share.grant",
      "share.revoke",
      "share.transfer",
      "share.move",
      "session.bind",
      "sources.unbind"
    ],
    "routines": [
      {
        "name": "collect",
        "cron": "*/30 * * * *",
        "check": {
          "tool": "mem.collect",
          "input": {}
        },
        "description": "Collect new events from your enabled sources into Memory"
      }
    ],
    "inbox": {
      "method": "inbox.list"
    }
  },
  "files": [
    "index.js",
    "src",
    "skills",
    "assets/icon.svg",
    "views/home.html",
    "views/memory.html",
    "views/commitments.html",
    "views/today.html",
    "views/journal.html",
    "views/review.html",
    "views/pages.html",
    "views/graph.html",
    "docs/agent-protocol.md",
    "docs/agent-instructions.md",
    "docs/permissions.md",
    "!docs/README.md",
    "README.md",
    "LICENSE",
    "SECURITY.md",
    "CHANGELOG.md",
    "views/recall.html",
    "views/remembered.html"
  ],
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "test": "node --experimental-strip-types --import ./test/support/tmp-isolation.js --test test/*.test.js",
    "test:load": "node --import ./test/support/tmp-isolation.js --test test/load-harness.test.js test/load-gateway.test.js",
    "test:ops": "node --import ./test/support/tmp-isolation.js --test test/ops-control.test.js",
    "test:eval": "node --import ./test/support/tmp-isolation.js --test test/agent-eval.test.js",
    "test:pack": "node --test test/package-contents.test.js",
    "test:records": "node --disable-warning=ExperimentalWarning --import ./test/support/tmp-isolation.js --test records/test/*.test.js",
    "eval:agent": "node scripts/eval/agent-eval.mjs",
    "eval:core": "node scripts/eval/agent-eval.mjs --suite core --runs 1 --timeout 120",
    "eval:core:release": "node scripts/eval/agent-eval.mjs --suite core --runs 3 --timeout 120",
    "eval:value": "node scripts/eval/agent-eval.mjs --suite value --runs 1 --timeout 120",
    "eval:value:release": "node scripts/eval/agent-eval.mjs --suite value --runs 3 --timeout 120",
    "eval:extended": "node scripts/eval/agent-eval.mjs --suite extended --runs 1",
    "eval:public": "node scripts/eval/agent-eval.mjs --suite public --runs 1",
    "eval:summary": "node scripts/eval/summarize.mjs",
    "eval:scorecard": "node scripts/eval/scorecard.mjs",
    "eval:closed-book": "node scripts/eval/agent-eval.mjs --suite core --closed-book --runs 1 --timeout 120 --scenario core-recall-model --scenario core-recall-orb --scenario core-recall-port --scenario core-recall-region --scenario core-prior-db --scenario core-prior-version --scenario core-source-attribution --scenario core-preference --scenario core-update-owner --scenario core-update-region",
    "eval:agent:list": "node scripts/eval/agent-eval.mjs --list",
    "eval:controls": "node scripts/eval/controls.mjs",
    "eval:regrade": "node scripts/eval/regrade.mjs",
    "eval:c1": "node scripts/eval/c1.mjs",
    "eval:gate-v2": "node scripts/eval/gate-v2.mjs",
    "eval:writes": "node scripts/eval/write-allowlist.mjs",
    "eval:asks": "node scripts/eval/ask-policy.mjs",
    "load:spaces": "node scripts/loadtest-spaces.mjs",
    "load:gateway": "node scripts/loadtest-gateway.mjs",
    "load:cell": "node scripts/loadtest-cell.mjs",
    "capacity:spaces": "node scripts/cell-capacity.mjs",
    "ops:backup": "node scripts/backup-control.mjs",
    "ops:restore": "node scripts/restore-control.mjs",
    "ops:drill": "node scripts/restore-drill.mjs",
    "build:ui": "npm --prefix ui ci --no-audit --no-fund && npm --prefix ui run build",
    "dev:ui": "npm --prefix ui run dev",
    "stub": "node stub/server.js",
    "install:plugin": "node scripts/install.mjs",
    "e2e": "node scripts/e2e.mjs",
    "e2e:stack": "node scripts/e2e/stack.mjs",
    "verify:stub": "node scripts/live-check.mjs",
    "skill:publish": "node scripts/publish-skill.mjs",
    "wiki:ingest": "node scripts/ingest-wiki.mjs",
    "repo:index": "node scripts/index-repo.mjs",
    "prune": "node scripts/prune.mjs",
    "space:export": "node scripts/space-export.mjs",
    "space:import": "node scripts/space-import.mjs",
    "space:purge": "node scripts/space-purge.mjs",
    "verify:edge": "node scripts/verify-edge.mjs",
    "test:control": "npm --prefix control test",
    "check:syntax": "node scripts/check-syntax.mjs",
    "check:docs": "node scripts/check-docs.mjs",
    "gen:protocol": "node scripts/gen-protocol.mjs",
    "check:protocol": "node scripts/gen-protocol.mjs --check",
    "check:docker": "node scripts/check-docker-imports.mjs",
    "check:compose": "node scripts/check-compose.mjs",
    "check:copies": "node scripts/check-copies.mjs",
    "check": "npm test && npm run check:syntax && npm run check:docs && npm run check:protocol && npm run check:copies",
    "check:jelly": "bun scripts/check-jelly-declaration.mjs",
    "check:jelly:master": "scripts/check-jelly-master.sh",
    "shots:views": "node scripts/view-shots.mjs"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "memory",
    "agent-memory",
    "team-memory"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/joe-broadhead/opencode-mem.git"
  },
  "homepage": "https://github.com/joe-broadhead/opencode-mem",
  "bugs": {
    "url": "https://github.com/joe-broadhead/opencode-mem/issues"
  }
}
